import { log } from "../logging.js";
export class Metrics {
    msgTypeCounts = {};
    totalPayloadBytes = 0;
    uniqueSenders = new Set();
    nonKeyhiveCount = 0;
    droppedSyncRequests = 0;
    messageCount = 0;
    totalProcessingTimeMs = 0;
    processingTimeByType = {};
    totalOps = 0n;
    hashLookupTimeMs = 0;
    eventLookupTimeMs = 0;
    cacheHits = 0;
    cacheMisses = 0;
    totalQueueWaitMs = 0;
    ingestCount = 0;
    eventsIngested = 0;
    pendingAfterIngest = 0;
    storageRetries = 0;
    opsSent = 0;
    opsRequested = 0;
    syncChecksSent = 0;
    syncChecksReceived = 0;
    syncChecksShortCircuited = 0;
    syncChecksFallback = 0;
    syncConfirmationsSent = 0;
    syncConfirmationsReceived = 0;
    recordMessage(msgType, senderId, payloadBytes) {
        const type = msgType ?? "unknown";
        this.msgTypeCounts[type] = (this.msgTypeCounts[type] ?? 0) + 1;
        this.totalPayloadBytes += payloadBytes;
        if (senderId)
            this.uniqueSenders.add(senderId);
        this.messageCount++;
    }
    recordNonKeyhive() {
        this.nonKeyhiveCount++;
    }
    recordDroppedSyncRequest() {
        this.droppedSyncRequests++;
    }
    recordProcessingTime(ms) {
        this.totalProcessingTimeMs += ms;
    }
    recordProcessingTimeByType(msgType, ms) {
        this.processingTimeByType[msgType] =
            (this.processingTimeByType[msgType] ?? 0) + ms;
    }
    recordTotalOps(ops) {
        this.totalOps = ops;
    }
    recordHashLookupTime(ms) {
        this.hashLookupTimeMs += ms;
    }
    recordEventLookupTime(ms) {
        this.eventLookupTimeMs += ms;
    }
    recordCacheHit() {
        this.cacheHits++;
    }
    recordCacheMiss() {
        this.cacheMisses++;
    }
    recordQueueWait(ms) {
        this.totalQueueWaitMs += ms;
    }
    recordIngestion(eventsCount, pendingCount) {
        this.ingestCount++;
        this.eventsIngested += eventsCount;
        this.pendingAfterIngest = pendingCount;
    }
    recordStorageRetry() {
        this.storageRetries++;
    }
    recordOpsSent(count) {
        this.opsSent += count;
    }
    recordOpsRequested(count) {
        this.opsRequested += count;
    }
    recordSyncCheckSent() {
        this.syncChecksSent++;
    }
    recordSyncCheckReceived() {
        this.syncChecksReceived++;
    }
    recordSyncCheckShortCircuited() {
        this.syncChecksShortCircuited++;
    }
    recordSyncCheckFallback() {
        this.syncChecksFallback++;
    }
    recordSyncConfirmationSent() {
        this.syncConfirmationsSent++;
    }
    recordSyncConfirmationReceived() {
        this.syncConfirmationsReceived++;
    }
    hasActivity() {
        return this.messageCount > 0 || this.nonKeyhiveCount > 0;
    }
    logReport(label) {
        if (!this.hasActivity())
            return;
        const countsStr = Object.entries(this.msgTypeCounts)
            .map(([type, count]) => `${type}=${count}`)
            .join(", ");
        log.debug(`[${label}] ${this.messageCount} keyhive messages from ${this.uniqueSenders.size} peers at ${new Date().toLocaleTimeString("en-GB")}. ` +
            `${this.droppedSyncRequests} duplicate sync requests dropped. ` +
            `${this.nonKeyhiveCount} non-keyhive messages. ` +
            `Breakdown: ${countsStr}. Total payload: ${this.totalPayloadBytes} bytes. ` +
            `Processing: ${this.totalProcessingTimeMs}ms.`);
        const perTypeStr = Object.entries(this.processingTimeByType)
            .map(([type, ms]) => `${type}=${ms}ms`)
            .join(", ");
        log.debug(`[${label}+] Per-type: ${perTypeStr}. ` +
            `Lookups: hash=${this.hashLookupTimeMs}ms, event=${this.eventLookupTimeMs}ms. ` +
            `Cache: ${this.cacheHits}/${this.cacheMisses} hit/miss. ` +
            `Queue wait: ${this.totalQueueWaitMs}ms. ` +
            `Ingestion: ${this.ingestCount}x, ${this.eventsIngested} events, ${this.pendingAfterIngest} pending, ${this.storageRetries} retries. ` +
            `Ops: ${this.opsSent} sent, ${this.opsRequested} requested. ` +
            `Sync checks: ${this.syncChecksSent} sent, ${this.syncChecksReceived} rcvd, ${this.syncChecksShortCircuited} short-circuited, ${this.syncChecksFallback} fallback. ` +
            `Confirmations: ${this.syncConfirmationsSent} sent, ${this.syncConfirmationsReceived} rcvd. ` +
            `Total ops: ${this.totalOps}`);
    }
}
